async function fetchWhopBusinessName(whopCompanyId: string): Promise<string | null> {
  const apiKey = process.env.WHOP_API_KEY;
  if (!apiKey) {
    console.log(`[fetchWhopBusinessName] Missing WHOP_API_KEY`);
    return null;
